  cols:['Date / time','Activity','Details'],
  rows:[['Mon 7:45 a.m.','Depart Seattle (SEA)<span class="sub">Flight AC 542</span>','[[Layover|layover]] in Vancouver (1 hr 20 min)'],
   ['Mon 2:10 p.m.','Arrive Toronto (YYZ)','[[Shuttle|shuttle]] to Lakeside Hotel'],
   ['Mon 6:30 p.m.','Dinner with clients','Marlowe Bistro'],
   ['Tue 9:00 a.m.','[[Site visit|sitevisit]]','Northgate [[Warehouse|warehouse]]'],
   ['Tue 1:00 p.m.','[[Quarterly|quarterly]] sales meeting','Toronto branch office'],
   ['Wed 11:00 a.m.','Hotel [[check-out|checkout]]','Lakeside Hotel'],
   ['Wed 1:30 p.m.','Depart Toronto (YYZ)<span class="sub">Flight AC 117</span>','[[Nonstop|nonstop]] to Seattle']],
